with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'ぶらんこ', 'ジャン・オノレ・フラゴナール', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Fragonard%2C_The_Swing.jpg/960px-Fragonard%2C_The_Swing.jpg', '1767年ごろに描かれた油彩画で、ロンドンのウォレス・コレクションが所蔵しています。劇作家コレの回想によれば、ある宮廷人が自分と愛人を描くよう画家ドワイヤンに頼み、断られた依頼がフラゴナールに回ったといいます。茂みに隠れた青年が、ぶらんこの上で靴を蹴り飛ばす女性を見上げ、その後ろでは年配の男性が綱を引いています。唇に指を当てる小さな像や、ふくらむドレスの色に、ロココ絵画の軽やかな遊び心が表れています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Fragonard,_The_Swing.jpg'),
    (2, '仁王霽色図', '鄭敾', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Inwangjesaekdo.jpg/960px-Inwangjesaekdo.jpg', '朝鮮王朝の画家・鄭敾が1751年に描いた紙本墨画で、韓国の国宝に指定されています。題名は、雨が上がったあとの漢陽（いまのソウル）の仁王山の姿を意味します。鄭敾は中国の南画から出発し、朝鮮の実際の山や川を描く「真景山水」を切り開きました。濃い墨を重ねた岩肌の量感と、白く残した部分の対比に、その描き方がよく表れています。李健熙の旧蔵品で、没後に韓国の国立中央博物館へ寄贈されました。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Inwangjesaekdo.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('アーティゾン美術館、2027年の展覧会発表', '新収蔵品展、荒川ナッシュ医の帰国展、藤島武二展など2027年の4つの企画展を発表。', 'アーティゾン美術館が2027年の展覧会スケジュールを発表した。2月23日から5月30日までの「ARTIZON NOW」では、初公開となる浮世絵や能装束をはじめ、新収蔵作品を中心に「アーティゾン美術館の今」を紹介する。6月19日から9月20日までは、第61回ヴェネチア・ビエンナーレ日本館展示の帰国展となる荒川ナッシュ医の展覧会と、近年寄贈された素描などを初公開する「藤島武二 ―創造の軌跡」を開く。10月16日からは、ジャスパー・ジョーンズやロバート・ライマンらの作品約60点に光を当てる「New Objectivity ―1960-70年代のアートシーン」を開催する。', '', '美術館', 'https://artexhibition.jp/topics/news/20261106-AEJ3035638/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('黒扇', 'Black Fan', '藤島武二', 'Fujishima Takeji',
        1908,
        (select slug from public.art_movements where slug = 'yoga-meiji'),
        'アーティゾン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Fujishima_Takeji_-_Black_Fan_-_Google_Art_Project.jpg/960px-Fujishima_Takeji_-_Black_Fan_-_Google_Art_Project.jpg', '1905年から文部省の命でフランスとイタリアに学んだ藤島武二が、留学中の1908〜09年ごろに描いた油彩画で、重要文化財に指定されています。イタリア人女性をモデルに、黒い扇を手にした姿を描いています。背景や衣服はすばやい筆で大まかにとらえ、顔と目もとに視線が集まるように描き分けているのが見どころです。白馬会の明るい外光表現を受け継ぎながら、イタリアで古典古代やルネサンスの美術に触れたことで、人物の存在感を前に出す方向へ進んだ時期の代表作です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Fujishima_Takeji_-_Black_Fan_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ポッピンを吹く娘', 'Young lady blowing on a poppin', '喜多川歌麿', 'Kitagawa Utamaro',
        1792,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        'メトロポリタン美術館ほか', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Flickr_-_%E2%80%A6trialsanderrors_-_Utamaro%2C_Young_lady_blowing_on_a_poppin%2C_1790.jpg/960px-Flickr_-_%E2%80%A6trialsanderrors_-_Utamaro%2C_Young_lady_blowing_on_a_poppin%2C_1790.jpg', '版元・蔦屋重三郎のもとで1792〜93年ごろに出された、歌麿の美人大首絵の初期の作品です。揃物の名は途中で「婦人相学十躰」から「婦女人相十品」に改められました。ガラスでできたおもちゃ「ポッピン」を吹く町娘を、胸から上の大きな構図で描いています。振り向いた勢いで翻る市松模様の振袖と、淡く光る雲母の背景の対比が見どころです。それまでの全身像の美人画から、顔や仕草で人柄や心の動きまで表そうとする方向へ、浮世絵の美人画を大きく進めました。',
        'CC BY 2.0', '…trialsanderrors', 'https://commons.wikimedia.org/wiki/File:Flickr_-_…trialsanderrors_-_Utamaro,_Young_lady_blowing_on_a_poppin,_1790.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
