insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('藤島武二', 'Fujishima Takeji', '藤島武二',
        1867, 1943, 'japan', array['yoga-meiji']::text[],
        '明治から昭和にかけて日本の洋画を導き、東京美術学校で多くの後進を育てた画家。', '薩摩国鹿児島の生まれです。はじめ日本画を学び、四条派の川端玉章に師事したのち、曽山幸彦らに洋画の基礎を学びました。1896年、黒田清輝の推薦で東京美術学校西洋画科の助教授となり、黒田が主宰する白馬会にも発足時から参加しました。

1905年からは文部省の命でフランスとイタリアに留学し、パリではフェルナン・コルモンに、ローマではカロリュス＝デュランに学びました。雑誌『明星』や与謝野晶子『みだれ髪』の装丁ではアール・ヌーヴォーの要素を取り入れ、作風はロマン主義的とされます。

代表作に『天平の面影』（1902年）や留学中の『黒扇』（1908〜09年）があり、どちらも重要文化財です。1910年に東京美術学校の教授となって亡くなるまで後進を指導し、1937年には第1回の文化勲章を受けました。', 'https://ja.wikipedia.org/wiki/%E8%97%A4%E5%B3%B6%E6%AD%A6%E4%BA%8C')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('鄭敾', 'Jeong Seon', '鄭敾',
        1676, 1759, 'east_asia', array['joseon']::text[],
        '朝鮮の実際の山水を描く「真景山水」を切り開いた、朝鮮王朝後期の画家。', '朝鮮王朝後期の画家で、号は謙斎などです。20歳のころ、金昌集の推薦で宮廷の絵画を担う図画署の画員となり、のちに県監の位にまで進みました。

はじめは中国の南画を学びましたが、30歳ごろから朝鮮の実際の山や川を写す真景山水に移り、その第一人者となりました。強い墨の濃淡や、岩肌に青みを使う新しい描き方を工夫しています。沈師正、趙栄祏とともに「三斎」と呼ばれました。

代表作の『仁王霽色図』と『金剛全図』は、どちらも韓国の国宝に指定されています。中国の手本をなぞるのではなく、自分の国の風景を描くという姿勢を示しました。', 'https://ja.wikipedia.org/wiki/%E9%84%AD%E6%95%BE')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アルノルト・ベックリン', 'Arnold Böcklin', 'ベックリン',
        1827, 1901, 'west', array['symbolism']::text[],
        '神話や死を題材に幻想的な画面を描いた、スイス出身の象徴主義の画家。', 'スイスのバーゼルに生まれ、1845年からドイツのデュッセルドルフで学びました。1850年から57年まではローマに滞在し、その後ヴァイマルの美術学校で教えたのち、ミュンヘン、フィレンツェ、チューリヒなどで制作しました。晩年はフィレンツェ郊外のフィエーゾレに住みました。

写実的で緻密な描き方と、神秘的・幻想的な雰囲気が特色です。同じ時代のフランス印象派とは対照的に、文学や神話、聖書などを題材にした、象徴主義の代表的な画家の一人とされます。

代表作『死の島』は1880年から86年にかけて5点が描かれ、ラフマニノフやレーガーが触発されて曲を書きました。『ヴァイオリンを弾く死神のいる自画像』（1872年）なども知られ、20世紀のシュルレアリスムにも大きな影響を与えました。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%AB%E3%83%8E%E3%83%AB%E3%83%88%E3%83%BB%E3%83%99%E3%83%83%E3%82%AF%E3%83%AA%E3%83%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
